import { ElevenLabsClient } from 'elevenlabs';
import fs from 'fs';
import path from 'path';

const client = new ElevenLabsClient({
  apiKey: process.env.ELEVENLABS_API_KEY,
});

async function textToSpeech(
  text: string,
  voiceId: string,
  outputPath: string
): Promise<void> {
  const audio = await client.textToSpeech.convert(voiceId, {
    text,
    model_id: 'eleven_multilingual_v2',
    voice_settings: {
      stability: 0.5,
      similarity_boost: 0.75,
    },
    output_format: 'mp3_44100_128',
  });

  // audio is a ReadableStream — collect all chunks into a Buffer
  const chunks: Buffer[] = [];
  for await (const chunk of audio) {
    chunks.push(Buffer.from(chunk));
  }
  const audioBuffer = Buffer.concat(chunks);

  fs.writeFileSync(outputPath, audioBuffer);
  console.log(`Audio saved to ${outputPath} (${audioBuffer.length} bytes)`);
}

// 'Rachel' is a popular pre-made ElevenLabs voice
const RACHEL_VOICE_ID = '21m00Tcm4TlvDq8ikWAM';

await textToSpeech(
  'Hello! This is a test of the ElevenLabs text-to-speech API.',
  RACHEL_VOICE_ID,
  path.join(process.cwd(), 'output.mp3')
);

import { ElevenLabsClient } from 'elevenlabs';
import { Writable } from 'stream';

const client = new ElevenLabsClient({
  apiKey: process.env.ELEVENLABS_API_KEY,
});

async function streamSpeechToOutput(
  text: string,
  voiceId: string,
  outputStream: Writable
): Promise<void> {
  const audioStream = await client.textToSpeech.stream(voiceId, {
    text,
    model_id: 'eleven_flash_v2_5', // Use Flash model for lowest latency
    voice_settings: {
      stability: 0.5,
      similarity_boost: 0.75,
    },
    output_format: 'pcm_16000', // PCM for real-time audio pipelines
  });

  return new Promise<void>((resolve, reject) => {
    audioStream.on('data', (chunk: Buffer) => {
      outputStream.write(chunk);
    });

    audioStream.on('end', () => {
      outputStream.end();
      resolve();
    });

    audioStream.on('error', (err: Error) => {
      reject(err);
    });
  });
}

// Example: stream to stdout (pipe to a media player like ffplay)
const RACHEL_VOICE_ID = '21m00Tcm4TlvDq8ikWAM';

await streamSpeechToOutput(
  'This audio streams in real-time with sub-500ms latency to first byte.',
  RACHEL_VOICE_ID,
  process.stdout
);
